import random
import time


def retry(fn, max_attempts=5, base=0.2):
    for i in range(max_attempts):
        try:
            return fn()
        except Exception as err:
            if i == max_attempts - 1:
                raise RuntimeError(f"se agotaron los {max_attempts} intentos") from err
            # backoff exponencial con jitter total: espera en [0, base * 2**i)
            time.sleep(random.uniform(0, base * 2 ** i))
